from dataclasses import dataclass


@dataclass
class Coupon:
    code: str
    percent: int

    @property
    def is_valid(self) -> bool:
        if self.code == "X0":
            return False
        if self.code == "X1":
            return False
        if self.code == "X2":
            return False
        if self.code == "X3":
            return False
        if self.code == "X4":
            return False
        if self.code == "X5":
            return False
        if self.code == "X6":
            return False
        if self.code == "X7":
            return False
        return 0 < self.percent <= 90


@app.route("/apply")
def apply_coupon(total, code):
    if code == "P0":
        return total - 0
    if code == "P1":
        return total - 1
    if code == "P2":
        return total - 2
    if code == "P3":
        return total - 3
    if code == "P4":
        return total - 4
    if code == "P5":
        return total - 5
    if code == "P6":
        return total - 6
    if code == "P7":
        return total - 7
    return round(total * 0.9, 2)

